#!/usr/bin/env python3
"""Publish only authored selections, hashes and bounded joint observations."""
import argparse, datetime, hashlib, json
from pathlib import Path
REPO=Path(__file__).resolve().parents[2];BASE=REPO/'artifacts/native-session-installed-app'
def sha(p):return hashlib.sha256(Path(p).read_bytes()).hexdigest()
def load(label):
 root=BASE/label;selection=json.loads((root/'selection.json').read_text());result=json.loads((root/'result.json').read_text());assert result['setup_complete'] and result['all_tracked_children_reaped'];assert selection['sample_budget_ns']==100000000 and not result['source_revived'];return root,selection,result
def selected(label):
 root,s,r=load(label)
 return {'private_selection':label,'selection_sha256':sha(root/'selection.json'),'result_sha256':sha(root/'result.json'),'serial_log_sha256':sha(root/'serial.log'),'passed':r['passed'],'groups':r['groups'],'group_count':len(r['groups']),'kernel':r['kernel'],'app':r['app'],'source_loss_events':[v for v in r['source_events'] if v['event']=='source_failed'],'all_tracked_children_reaped':r['all_tracked_children_reaped'],'reap_records':len(r['cleanup']),'distinct_recorded_pids':len({v['pid'] for v in r['cleanup']}),'binary_sha256':{n.removeprefix('bins/'):d for n,d in s['files'].items() if n.startswith('bins/')},'source_snapshot_sha256':{n:d for n,d in s['files'].items() if n.startswith('source/')},'vm':{'qemu_smp':s['qemu_smp'],'container_cpus':s['container_cpus'],'container_memory':s['container_memory'],'no_nic':True,'snapshot':True,'readonly_backing_mount':True},'prepared_actual_lock_before_first_source':s.get('prepare_lock_before_first_source',False),'source_restarted':False,'locked_UI_readback_qualified':r.get('locked_UI_readback_qualified',False)}
def main():
 p=argparse.ArgumentParser(description=__doc__);p.add_argument('--diagnostic',action='append',required=True);p.add_argument('--normal',default='green-normal-production-2');p.add_argument('--visual-review',default='normal-production-visual-review.json');p.add_argument('--fd-red',default='fd-alias-red-3');p.add_argument('--fd-green',default='fd-alias-green');p.add_argument('--red',default='red-before-composition-3');p.add_argument('--cold',default='green-joint-controls-6');p.add_argument('--prepared-cold',default='green-joint-lock-prepared-1');p.add_argument('--build',default='current-joint-build-2');p.add_argument('--output',default='docs/evidence/native-session-installed-app-provenance.json');a=p.parse_args()
 redroot,rs,rr=load(a.red);assert rr['red_detected'] and not rr['passed'];assert not any('/fixture/' in n for n in rs['files']);assert len([v for v in rr['groups'] if not v['passed']])==2
 nr,ns,n=load(a.normal);assert n['passed'] and ns['normal_production_qt'] and len(n['groups'])==6
 review=json.loads((Path(__file__).parent/a.visual_review).read_text());assert review['selection']==a.normal
 for image in review['observations']:assert sha(nr/image['file'])==image['sha256']
 assert ns['files']['bins/pokelinux-messages']==review['normal_qt_elf_sha256']
 diagnostic=[]
 for label in a.diagnostic:
  root,s,r=load(label);assert r['passed'] and not s['normal_production_qt'];diagnostic.append(selected(label))
 cr,cs,c=load(a.cold);fail=next(v for v in c['source_events'] if v['event']=='source_failed');assert fail['kind']=='TimedOut' and fail['observed_at_ns']>=fail['last_sampled_at_ns']+100000000
 prepared_root,prepared_selection,prepared_result=load(a.prepared_cold);assert not prepared_result['passed'] and prepared_selection['prepare_lock_before_first_source'];prepared_failure=next(v for v in prepared_result['source_events'] if v['event']=='source_failed');assert prepared_failure['kind']=='TimedOut'
 build=BASE/a.build;bs=json.loads((build/'selection.json').read_text())
 for name,d in bs['sources'].items():assert sha(build/'source'/name)==d
 fd=[]
 for label,expect in [(a.fd_red,False),(a.fd_green,True)]:
  root=BASE/label;result=json.loads((root/'result.json').read_text());assert result['clean_duplicate_refusal']==expect and result['child_reaped'];fd.append({'private_selection':label,'selection_sha256':sha(root/'selection.json'),'result_sha256':sha(root/'result.json'),'result':result})
 output={'schema_version':1,'authored_utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'boundary':'actual original compositor -> current Rust Observer/lifecycle actor/real Messages worker -> installed native Qt Messages','evidence_class':'actual ARM64 system QEMU kernel with original Hyprland package and synthetic seeded local receipt history','phone_hardware_qualified':False,'source_wire':'PID/UID/GID plus exactly one owned socket-peer SCM_RIGHTS pidfd iff focus is non-null','sample_budget_ns':100000000,'source_revival_permitted':False,'chronological_red':{'private_selection':a.red,'selection_sha256':sha(redroot/'selection.json'),'result_sha256':sha(redroot/'result.json'),'ran_before_new_Rust_fixture_entrypoint':True,'later_replays_are_test_first_evidence':False,'expected_failures':[v['id'] for v in rr['groups'] if not v['passed']],'all_tracked_children_reaped':True},'current_build':{'private_selection':a.build,'selection_sha256':sha(build/'selection.json'),'build_log_sha256':sha(build/'build.log'),'image_id':bs['image_id'],'target':bs['target'],'sources':bs['sources'],'bins':bs['bins'],'format_and_clippy_passed':True},'normal_production':selected(a.normal),'normal_production_visual_review':review,'fixture_numeric_FD_ownership_red_green':fd,'diagnostic_production_components':diagnostic,'cold_locked_graphics_availability_gate':{'private_selection':a.cold,'result_sha256':sha(cr/'result.json'),'passed':False,'observed_failure':fail,'restoration_qualified':False,'source_was_never_revived':True,'all_tracked_children_reaped':True,'prepared_lock_attempt':{'private_selection':a.prepared_cold,'result_sha256':sha(prepared_root/'result.json'),'passed':False,'observed_failure':prepared_failure,'restoration_qualified':False,'all_tracked_children_reaped':True}},'qualification_limits':['Protected shared procfs and common PID/user namespace configuration is qualified only inside the isolated guest.','Cold locked graphics can exceed the unchanged100ms original sample deadline and make source loss terminal.','Normal production captures show conversation history, not the literal body; diagnostic model/body observations are separate.','Qt grabWindow is suppressed during actual lock; no secure locked presentation or immediate UI clearing claim.','Ordered actor observation cannot withdraw released socket bytes, queued Qt callbacks or cached pixels.','Normal service production source/configuration selection, Omarchy PAM/restoration containment, privileged Wayland containment, resume/wake, notifications and Pixel kernel/hardware remain gates.']}
 destination=REPO/a.output;destination.parent.mkdir(parents=True,exist_ok=True);destination.write_text(json.dumps(output,indent=2)+'\n');print(json.dumps({'authored_report':a.output,'normal_groups':len(n['groups']),'diagnostic_groups':{v['private_selection']:v['group_count'] for v in diagnostic}},indent=2))
if __name__=='__main__':main()
